using Microsoft.ML.Data;

namespace ChurnPredictor;

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    [ColumnName("Label")]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    [ColumnName("Probability")]
    public float Probability { get; set; }

    [ColumnName("Score")]
    public float Score { get; set; }
}

using Microsoft.ML;

namespace ChurnPredictor;

public class ChurnModelService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<ChurnModelService> _logger;
    private ITransformer? _model;

    public string ModelPath { get; }

    public ChurnModelService(ILogger<ChurnModelService> logger)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
        ModelPath = Path.Combine(AppContext.BaseDirectory, "Data", "ChurnModel.zip");
    }

    public void TrainAndSave()
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
        var dataView = _mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
            .Append(_mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
            .Append(_mlContext.Transforms.Concatenate("Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
            .Append(_mlContext.BinaryClassification.Trainers.SdcaLogisticRegression())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions);

        _logger.LogInformation("Model Accuracy: {Accuracy:F4}", metrics.Accuracy);
        _logger.LogInformation("Model AUC: {Auc:F4}", metrics.AreaUnderRocCurve);
        _logger.LogInformation("Model F1: {F1:F4}", metrics.F1Score);

        Directory.CreateDirectory(Path.GetDirectoryName(ModelPath)!);
        _mlContext.Model.Save(_model, dataView.Schema, ModelPath);
        _logger.LogInformation("Model saved to {Path}", ModelPath);
    }

    public ChurnPrediction Predict(CustomerData input)
    {
        if (_model is null)
            throw new InvalidOperationException("Model has not been trained yet.");

        var engine = _mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(_model);
        return engine.Predict(input);
    }
}

