using ChurnPredictor;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();

var app = builder.Build();

// Train model on startup
var modelService = app.Services.GetRequiredService<ChurnModelService>();
modelService.TrainAndSave();

// Register PredictionEnginePool after model is saved
builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton(modelService);
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath: modelService.ModelPath);

app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (CustomerData input,
    PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Json(prediction);
});

app.MapGet("/predict", (float age, float income, string region, float purchaseHistory,
    PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var input = new CustomerData
    {
        Age = age,
        Income = income,
        Region = region,
        PurchaseHistory = purchaseHistory
    };
    var prediction = pool.Predict(input);
    return Results.Json(prediction);
});

app.Run();

